/**
 * Logo de Cliché embebido en base64 para los correos (adjunto inline CID).
 *
 * ¿Por qué embebido y no una URL? El dominio apex clichecolombia.com responde
 * 308 → www, y varios clientes de correo NO siguen redirects al cargar
 * imágenes: el logo salía roto o en blanco. Un adjunto inline (cid:) se
 * muestra siempre, incluso con las imágenes remotas bloqueadas.
 *
 * Fuente: public/images/logo-cliche.png — si el logo cambia, regenerar con:
 *   node -e "console.log(require('fs').readFileSync('public/images/logo-cliche.png').toString('base64'))"
 */
export const LOGO_PNG_BASE64 =
  ''
